/* From Uiverse.io by barisdogansutcu  - Tags: icon, button, css icon */
.__UIV_SCOPE__ .text {
  font-size: 5px;
  position: absolute;
  top: 3px;
  color: #2f363d;
  opacity: 0;
}
.__UIV_SCOPE__ .icons {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  place-content: center;
  gap: 5px;
}
.__UIV_SCOPE__ .title {
  grid-column-start: 1;
  grid-column-end: 5;
  text-align: center;
  font-weight: 100;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.__UIV_SCOPE__ .title span {
  text-shadow: 1px 1px #ffffff;
}
.__UIV_SCOPE__ .icon-box:hover {
  transform: scale(2);
  z-index: 9;
}
.__UIV_SCOPE__ .icon-box {
  background-color: #ffffff;
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: rgba(99, 99, 99, 0.2) 0px 2px 8px 0px;
  border-radius: 5px;
  transition: all 0.2s ease;
  position: relative;
}
.__UIV_SCOPE__ .icon-box:hover .text {
  opacity: 1;
}
.__UIV_SCOPE__ .icon-box:hover button {
  margin-top: 5px;
}
.__UIV_SCOPE__ button {
  background-color: transparent;
  z-index: 0;
  margin-top: 0px;
}
.__UIV_SCOPE__ .activity {
  position: relative;
  width: 30px;
  height: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: none;
  cursor: pointer;
}
.__UIV_SCOPE__ .activity .line-1 {
  display: inline-flex;
  width: 8px;
  height: 2px;
  border-radius: 50px;
  background-color: #2f363d;
}
.__UIV_SCOPE__ .activity .line-2 {
  display: inline-flex;
  width: 9px;
  height: 2px;
  border-radius: 50px;
  background-color: #2f363d;
  transform: rotate(-75deg);
  margin-top: -8px;
  margin-left: -4px;
}
.__UIV_SCOPE__ .activity .line-3 {
  display: inline-flex;
  width: 16px;
  height: 2px;
  border-radius: 50px;
  background-color: #2f363d;
  transform: rotate(70deg);
  margin-top: -3px;
  margin-left: -9px;
}
.__UIV_SCOPE__ .activity .line-4 {
  display: inline-flex;
  width: 8px;
  height: 2px;
  border-radius: 50px;
  background-color: #2f363d;
  transform: rotate(-70deg);
  margin-top: 6px;
  margin-left: -8px;
}
.__UIV_SCOPE__ .activity .line-5 {
  display: inline-flex;
  width: 8px;
  height: 2px;
  border-radius: 50px;
  background-color: #2f363d;
  margin-top: 0px;
  margin-left: -3px;
}
/* ----- */
.__UIV_SCOPE__ .airplay {
